# Doğru medyan mantığı:
# cnt = 21 (tek) -> medyan = eleman 11
# cnt = 30 (çift) -> medyan = (eleman 15 + eleman 16) / 2
# cnt = 38 (çift) -> medyan = (eleman 19 + eleman 20) / 2
# cnt = 10 (çift) -> medyan = (eleman 5 + eleman 6) / 2
# cnt = 24 (çift) -> medyan = (eleman 12 + eleman 13) / 2

def expected_median_rns(cnt):
    if cnt % 2 == 1:
        mid = (cnt + 1) // 2
        return (mid,)
    else:
        mid = cnt // 2
        return (mid, mid + 1)

for cnt in [21, 30, 38, 10, 24]:
    print(f"cnt={cnt} -> rn={expected_median_rns(cnt)}")

